    await page.goto(`${base}/music-studio.html#music-studio`,{waitUntil:'networkidle'});await page.waitForFunction(()=>MusicStudio?.state.loaded===true);
    await page.evaluate(async crossing=>{
      const app=MusicStudio,core=MusicStudioEditor,p=app.makeProject({projectId:'boundary',projectName:'Synthetic exact adoption',midiData:{ppq:480,tempo:120,timeSignature:{numerator:4,denominator:4},timeSignatureMap:[{tick:1000,numerator:3,denominator:8}],tempoMap:[{tick:777,bpm:60}],editor:{measureCount:4,editRange:{startMeasure:1,endMeasure:2},lockedMeasures:crossing?[]:[1]},tracks:[{id:'melody',part:'melody',notes:crossing?[{id:'crossing',pitch:62,startTick:900,durationTicks:400,velocity:90}]:[]},{id:'bass',part:'bass',notes:[]},{id:'drums',part:'drums',notes:[]}]}});
      if(!crossing){const s=core.createCoordinatedSession(p);MusicStudioMeasureLocks.unlockRange(s,core,{trackId:'melody',startTick:0,endTick:1000});MusicStudioMeasureLocks.addRangeLock(s,core,{trackId:'melody',startTick:1000,endTick:1720});p.midiData=structuredClone(s.midiData)}
      const repo=app.memoryRepository();await repo.put(p);let writes=0;const put=repo.put;repo.put=async p=>{writes++;return put(p)};window.__boundaryRepo=repo;window.__boundaryWrites=()=>writes;app.setRepository(repo);app.state.projects=[p];location.hash='music-studio/midi-editor/boundary';
    },crossing);
    await page.waitForSelector('.music-ai-panel');await page.waitForTimeout(400);assert.equal(await page.evaluate(()=>__boundaryWrites()),0);
    await page.getByRole('button',{name:'A/B/C候補'}).click();await page.selectOption('#aiCandidateKind','melody');await page.getByRole('button',{name:'A/B/Cを生成',exact:true}).click();await page.waitForSelector('.music-ai-candidates article');await page.fill('#aiFromA','1');await page.fill('#aiToA','1');const card=page.locator('.music-ai-candidates article').first();
    const before=await page.evaluate(()=>structuredClone(MusicStudioEditor.currentTrack(MusicStudio.state.midiEditor).notes));await card.getByRole('button',{name:'MIDI Preview'}).click();assert.equal(await page.inputValue('#aiToA'),'1');assert.deepEqual(await page.evaluate(()=>structuredClone(MusicStudioEditor.currentTrack(MusicStudio.state.midiEditor).notes)),before);
    const undoBefore=await page.evaluate(()=>MusicStudio.state.midiEditor.undo.length);await card.getByRole('button',{name:'PreviewをApply'}).click();
    if(crossing){assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('boundary').message.includes('candidate-selection-boundary')),true);assert.deepEqual(await page.evaluate(()=>structuredClone(MusicStudioEditor.currentTrack(MusicStudio.state.midiEditor).notes)),before);assert.equal(await page.evaluate(()=>MusicStudio.state.midiEditor.undo.length),undoBefore);assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('boundary').state.workspace.candidateSets.at(-1).adopted.length),0);await page.fill('#aiToA','0');await card.getByRole('button',{name:'PreviewをApply'}).click();assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('boundary').message.includes('invalid-candidate-selection')),true);assert.deepEqual(await page.evaluate(()=>structuredClone(MusicStudioEditor.currentTrack(MusicStudio.state.midiEditor).notes)),before)}
