async function arrangementReferenceCases(browser,base,width,inspectTracks=false){
 const reports=[];
 for(const mode of ['normal','missing','duplicate','invalid','stale-workspace','stale-midi','legacy',...(inspectTracks?['missing-role','ambiguous-role','duplicate-track-id']:[])]){
  const page=await browser.newPage({viewport:{width,height:1000}}),messages=[],external=[];
  page.on('console',m=>{if(['error','warning'].includes(m.type()))messages.push({type:m.type(),text:m.text()})});page.on('pageerror',e=>messages.push({type:'pageerror',text:e.message}));
  await page.route('**/*',route=>{const url=route.request().url();if(url.startsWith(base+'/')||url.startsWith('data:'))return route.continue();external.push(url);return route.abort()});
  await page.goto(`${base}/music-studio.html#music-studio`,{waitUntil:'networkidle'});await page.waitForFunction(()=>MusicStudio?.state.loaded===true);
  await page.evaluate(async()=>{
   const app=MusicStudio,p=app.makeProject({projectId:'arrangement-reference',projectName:'Synthetic Arrangement refs',midiData:{ppq:480,tempo:120,timeSignature:{numerator:4,denominator:4},editor:{measureCount:4,editRange:{startMeasure:1,endMeasure:4}},tracks:[{id:'melody',part:'melody',notes:[]},{id:'bass',part:'bass',notes:[]},{id:'drums',part:'drums',notes:[]}]}}),repo=app.memoryRepository();await repo.put(p);let writes=0;const put=repo.put;repo.put=async p=>{writes++;return put(p)};window.__arrRepo=repo;window.__arrWrites=()=>writes;app.setRepository(repo);app.state.projects=[p];location.hash='music-studio/midi-editor/arrangement-reference';
  });
  await page.waitForSelector('.music-ai-panel');await page.getByRole('button',{name:'A/B/C候補'}).click();await page.getByRole('button',{name:'Family A/B/Cを生成'}).click();
  await page.evaluate(mode=>{const r=MusicStudioAIAssistantPanel._states.get('arrangement-reference'),ws=r.state.workspace,chord=ws.candidateSets.find(x=>x.kind==='chord');if(mode==='missing')ws.candidateSets=ws.candidateSets.filter(x=>x!==chord);if(mode==='duplicate')ws.candidateSets.push(structuredClone(chord));if(mode==='invalid')chord.candidates[1].value.key='G';if(mode==='missing-role')MusicStudio.state.midiEditor.midiData.tracks=MusicStudio.state.midiEditor.midiData.tracks.filter(track=>track.id!=='bass');if(mode==='ambiguous-role')MusicStudio.state.midiEditor.midiData.tracks.push({id:'other',part:'melody',notes:[]});if(mode==='duplicate-track-id')MusicStudio.state.midiEditor.midiData.tracks.push({id:'melody',part:'drums',notes:[]});r.state.activeCandidateSetId=ws.candidateSets.find(x=>x.kind==='arrangement').setId;r.pending=false;MusicStudio.repaintEditor()},mode);
  await page.fill('#aiFromB','3');await page.fill('#aiToB','4');const card=page.locator('.music-ai-candidates article').nth(1),before=await page.evaluate(()=>JSON.stringify({ws:MusicStudioAIAssistantPanel._states.get('arrangement-reference').state.workspace,midi:MusicStudio.state.midiEditor.midiData,undo:MusicStudio.state.midiEditor.undo}));
  if(mode==='legacy'){assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('arrangement-reference').arrangementReferencePreview||null),null)}
  else{
   await card.getByRole('button',{name:inspectTracks?'Role / Track対応を確認':'Section / Chord参照を確認',exact:true}).click();
   if(['missing','duplicate','invalid','missing-role','ambiguous-role','duplicate-track-id'].includes(mode)){assert.match(await page.locator('.music-ai-candidate-status').textContent(),/arrangement-(chord-reference|track-role|track-id)/,mode);assert.doesNotMatch(await card.textContent(),/Arrangement reference identities verified/)}
   else{
    assert.match(await card.textContent(),/Arrangement reference identities verified/);assert.match(await card.textContent(),/Arrangement entry anchors: 0/);if(inspectTracks)assert.match(await card.textContent(),/Existing role tracks verified/);assert.equal(await page.inputValue('#aiFromB'),'3');
    if(mode.startsWith('stale')){await page.evaluate(mode=>{if(mode==='stale-workspace')MusicStudioAIAssistantPanel._states.get('arrangement-reference').state.workspace.future=1;else MusicStudio.state.midiEditor.midiData.tracks[0].notes.push({id:'new',pitch:60,startTick:0,durationTicks:480,velocity:90});MusicStudio.repaintEditor()},mode);assert.doesNotMatch(await card.textContent(),/Arrangement reference identities verified/);assert.match(await card.textContent(),/再確認/)}
    await page.screenshot({path:`music-ai-arrangement-${inspectTracks?'track':'reference'}-${mode}-${width}.png`,fullPage:true});await card.getByRole('button',{name:'編成参照取消',exact:true}).click();assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('arrangement-reference').arrangementReferencePreview),null);
   }
  }
  assert.equal(await page.evaluate(()=>MusicStudioAIAssistantPanel._states.get('arrangement-reference').pending),false);assert.equal(await page.evaluate(()=>__arrWrites()),0);
  if(!mode.startsWith('stale'))assert.equal(await page.evaluate(()=>JSON.stringify({ws:MusicStudioAIAssistantPanel._states.get('arrangement-reference').state.workspace,midi:MusicStudio.state.midiEditor.midiData,undo:MusicStudio.state.midiEditor.undo})),before);
  if(mode==='normal'){await card.getByRole('button',{name:inspectTracks?'Role / Track対応を確認':'Section / Chord参照を確認',exact:true}).click();await page.evaluate(()=>{MusicStudioAIAssistantPanel._states.get('arrangement-reference').pending=true});assert.equal((await page.evaluate(()=>MusicStudio.saveMidiEditor({silent:true}))).ok,true);const saved=await page.evaluate(()=>__arrRepo.get('arrangement-reference'));assert.doesNotMatch(JSON.stringify(saved),/arrangement-reference-preview|trackTargets|workspaceSignature|midiSignature/);await page.evaluate(saved=>{MusicStudio.state.midiEditor=MusicStudioEditor.createCoordinatedSession(saved);MusicStudio.repaintEditor()},saved);assert.doesNotMatch(await card.textContent(),/Arrangement reference identities verified/)}
  assert.deepEqual(messages,[]);assert.deepEqual(external,[]);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:`music-ai-arrangement-${inspectTracks?'track':'reference'}-final-${mode}-${width}.png`,fullPage:true});reports.push({case:mode,messages,external});await page.close();
 }
 return reports;
}

